async function confirm({ key, phase, image, asset, banner, statusCode, body }, ctx) {
  const state = await ctx.state.get(key);
  if (!state || state.phase !== phase || !state.pending) throw Error("Missing pending step");
  if (phase === "generate") {
    const url = image?.data?.[0]?.url;
    if (!/^https:\/\//.test(url || "")) throw Error("Image generation did not return a URL");
    state.generatedUrl = url;
    state.phase = "upload";
  } else if (phase === "upload") {
    if (!/^https:\/\//.test(asset?.secureUrl || ""))
      throw Error("Cloudinary did not return a secure URL");
    state.uploadUrl = asset.secureUrl;
    state.phase = "render";
  } else if (phase === "render") {
    const url = banner?.image_url_jpg || banner?.image_url;
    if (banner?.status !== "completed" || !/^https:\/\//.test(url || ""))
      throw Error("Banner was not completed");
    state.bannerUrl = url;
    state.phase = "send";
  } else if (phase === "send") {
    if (statusCode < 200 || statusCode >= 300 || !body?.id)
      throw Error("Discord attachment was not confirmed");
    state.phase = "done";
  } else throw Error("Unknown step");
  state.pending = null;
  await ctx.state.set(key, state);
  return { ok: true };
}

export default async function run(input, ctx) {
  return confirm({ ...input, phase: "generate" }, ctx);
}

